"""Read-only guard for SQL statements generated by the AI assistant."""

import re

__all__ = ["UnsafeSQLError", "assert_read_only"]


class UnsafeSQLError(ValueError):
    """Raised when a SQL statement is not guaranteed to be read-only."""


_WRITE_KEYWORDS = (
    "insert",
    "update",
    "delete",
    "drop",
    "alter",
    "create",
    "truncate",
    "grant",
    "revoke",
    "copy",
    "attach",
    "pragma",
)

_FORBIDDEN_FUNCTIONS = (
    "read_parquet",
    "read_csv",
    "read_json",
    "read_blob",
    "parquet_scan",
    "csv_scan",
    "json_scan",
    "glob",
)

_WRITE_START_RE = re.compile(rf"^({'|'.join(_WRITE_KEYWORDS)})\b", re.IGNORECASE)
_FORBIDDEN_FUNCTION_RE = re.compile(rf"\b({'|'.join(_FORBIDDEN_FUNCTIONS)})\s*\(", re.IGNORECASE)


def _strip_strings_and_comments(sql: str) -> str:
    """Blank out string literals and comments so they cannot hide keywords."""
    out = []
    i, n = 0, len(sql)
    while i < n:
        ch = sql[i]
        if ch in "'\"":
            quote = ch
            i += 1
            while i < n:
                if sql[i] == quote:
                    if i + 1 < n and sql[i + 1] == quote:
                        i += 2
                        continue
                    i += 1
                    break
                if sql[i] == "\\" and i + 1 < n:
                    i += 2
                else:
                    i += 1
            out.append(" ")
        elif sql[i : i + 2] == "--":
            while i < n and sql[i] != "\n":
                i += 1
        elif sql[i : i + 2] == "/*":
            end = sql.find("*/", i + 2)
            i = n if end == -1 else end + 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def _leading_write_keyword(statement: str) -> bool:
    """Return True if the statement's leading keyword is a write keyword.

    Skips leading ``WITH <name> AS (...)`` CTE clauses and parenthesized groups.
    """
    rest = statement.strip()
    if re.match(r"with\b", rest, re.IGNORECASE):
        rest = re.sub(r"with\b", "", rest, count=1, flags=re.IGNORECASE)
        cte = re.compile(r"^\s*[A-Za-z_]\w*\s+as\s*\([^()]*\)\s*,?", re.IGNORECASE)
        while cte.match(rest):
            rest = cte.sub("", rest, count=1)
    while rest.startswith("("):
        depth = 0
        for i, ch in enumerate(rest):
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    rest = rest[i + 1 :].strip()
                    break
        else:
            break
    return bool(_WRITE_START_RE.match(rest))


def assert_read_only(sql: str) -> None:
    """Raise UnsafeSQLError unless sql is a single read-only statement."""
    cleaned = _strip_strings_and_comments(sql)
    statements = [s for s in cleaned.split(";") if s.strip()]
    if len(statements) > 1:
        raise UnsafeSQLError("Multiple SQL statements are not allowed")
    if not statements:
        raise UnsafeSQLError("Empty SQL statement")
    statement = statements[0]
    if _FORBIDDEN_FUNCTION_RE.search(statement):
        raise UnsafeSQLError("Forbidden file function call")
    if _leading_write_keyword(statement):
        raise UnsafeSQLError("Write keyword at statement start")
